package com.kelompok4.oralhealthplus.data.repository

import com.kelompok4.oralhealthplus.data.local.SessionManager
import com.kelompok4.oralhealthplus.data.local.dao.DetectionHistoryDao
import com.kelompok4.oralhealthplus.data.local.entity.DetectionHistoryEntity
import com.kelompok4.oralhealthplus.data.model.DetectionResult
import com.kelompok4.oralhealthplus.data.model.DiseaseDescriptions
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.withContext

class HistoryRepository(private val dao: DetectionHistoryDao, private val sessionManager: SessionManager) {
  fun observeAllHistory(): Flow<List<DetectionHistoryEntity>> = dao.observeAllHistory()
  fun observeLatestDetection(): Flow<DetectionHistoryEntity?> = dao.observeLatestDetection()
  suspend fun getLatestDetection(): DetectionHistoryEntity? = withContext(Dispatchers.IO) { dao.getLatestDetection() }
  suspend fun simpanHasil(hasil: DetectionResult, imageUri: String? = null, catatanKeluhan: String = ""): Long {
    if (hasil.ditolak) return -1L
    val username = sessionManager.getLoggedInUsername() ?: "guest"
    val urgensi = (hasil.urgensi ?: DiseaseDescriptions.defaultUrgensiFor(hasil.kelas, hasil.confidence)).name
    val deskripsi = DiseaseDescriptions.getDescription(hasil.kelas)
    return withContext(Dispatchers.IO) {
      dao.insertHistory(
        DetectionHistoryEntity(
          username = username,
          kelas = hasil.kelas,
          confidence = hasil.confidence,
          urgensi = urgensi,
          deskripsi = deskripsi,
          catatanKeluhan = catatanKeluhan.trim().take(500),
          imageUri = imageUri
        )
      )
    }
  }
  suspend fun updateCatatanKeluhan(id: Int, catatanBaru: String): Boolean = withContext(Dispatchers.IO) { dao.updateCatatanKeluhan(id, catatanBaru.trim().take(500)) > 0 }
  suspend fun hapusRiwayat(id: Int): Boolean = withContext(Dispatchers.IO) { dao.deleteById(id) > 0 }
  suspend fun hapusSemuaRiwayat(): Int = withContext(Dispatchers.IO) { dao.deleteAll() }
}
